-- AD3 CHECK (read-only): one row per rule, ok must be true on every row. Run through ad-sql-run.sh after AD03.sql.
SELECT 'all 7 new AD3 tables exist with RLS enabled and forced' AS rule, (SELECT count(*) FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relkind = 'r' AND c.relrowsecurity AND c.relforcerowsecurity AND c.relname IN ('fadm_alert_state','fadm_alert_event','fadm_service','fadm_probe','fadm_incident','fadm_incident_update','fadm_alert_watch')) = 7 AS ok
UNION ALL SELECT 'every desk table is fadm_* with RLS enabled and forced', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relkind = 'r' AND (c.relname NOT LIKE 'fadm\_%' OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity))
UNION ALL SELECT 'desk_app has no write on any AD3 table', NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace s ON s.oid = c.relnamespace WHERE s.nspname = 'desk' AND c.relname IN ('fadm_alert_state','fadm_alert_event','fadm_service','fadm_probe','fadm_incident','fadm_incident_update','fadm_alert_watch','fadm_alert') AND (has_table_privilege('desk_app', c.oid, 'INSERT') OR has_table_privilege('desk_app', c.oid, 'UPDATE') OR has_table_privilege('desk_app', c.oid, 'DELETE')))
UNION ALL SELECT 'severity ladder is info, notice, high, critical', EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fadm_alert_severity_ck' AND pg_get_constraintdef(oid) ILIKE '%critical%')
UNION ALL SELECT 'alert event history is append-only (trigger)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_alert_event'::regclass AND tgname = 'fadm_alert_event_guard')
UNION ALL SELECT 'incident update feed is append-only (trigger)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_incident_update'::regclass AND tgname = 'fadm_incident_update_guard')
UNION ALL SELECT 'probe log is append-only (trigger)', EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.fadm_probe'::regclass AND tgname = 'fadm_probe_guard')
UNION ALL SELECT 'every alert has a state row', NOT EXISTS (SELECT 1 FROM desk.fadm_alert a WHERE NOT EXISTS (SELECT 1 FROM desk.fadm_alert_state s WHERE s.alert_id = a.id))
UNION ALL SELECT 'ten services in the closed list, the critical ones marked', (SELECT count(*) FROM desk.fadm_service) >= 10 AND (SELECT count(*) FROM desk.fadm_service WHERE critical) >= 6
UNION ALL SELECT 'the six Bridge policies exist (deny by default stays)', (SELECT count(*) FROM desk.fadm_policy WHERE name IN ('p_alert_read','p_alert_ack','p_alert_assign','p_alert_resolve','p_health_read','p_incident_manage')) = 6
UNION ALL SELECT 'Bridge ledger kinds are on the closed list', (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('alert.critical','alert.ack','alert.assign','alert.status','alert.note','service.outage','service.recovered','incident.opened','incident.updated','incident.closed','watch.changed')) = 11
UNION ALL SELECT 'closed alerts always carry a closed_at (constraint)', EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fadm_alert_state_closed_ck')
UNION ALL SELECT 'the Bridge doors are granted to desk_app', has_function_privilege('desk_app', 'desk.fadm_bridge_summary(uuid,inet)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_alert_act(uuid,bigint,text,text,uuid,text,inet)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.fadm_probe_record(text,boolean,integer,jsonb)', 'EXECUTE')
UNION ALL SELECT 'no PUBLIC execute on Desk functions', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.proname LIKE 'fadm\_%' AND has_function_privilege('public', p.oid, 'EXECUTE'))
UNION ALL SELECT 'all SECURITY DEFINER functions pin search_path', NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace s ON s.oid = p.pronamespace WHERE s.nspname = 'desk' AND p.prosecdef AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')))
UNION ALL SELECT 'desk_app is no superuser and does not bypass RLS', NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'desk_app' AND (rolsuper OR rolbypassrls))
UNION ALL SELECT 'live probes run every 4 s so a heartbeat is stale at 12 s (his rule)', (SELECT count(*) FROM desk.fadm_service WHERE service IN ('h3_edge','tls','db','signer') AND probe_every_s = 4) = 4
UNION ALL SELECT 'ledger hash chain still verifies', desk.fadm_ledger_verify();
